13	std::complex<double> Fvf(int st, int j1, int j2, int j3, int j4, int j5, int j6,
14	                          FArray2D<std::complex<double>>& za,
15	                          FArray2D<std::complex<double>>& zb) {
16	  using namespace mxpart_mod;
17	  using namespace sprods_com_mod;
18	  using namespace heldefs_mod;
19	
20	  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) -> std::complex<double> {
21	    return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
22	  };
23	
24	  std::complex<double> I3m123456 = i3m(s(j1,j2), s(j3,j4), s(j5,j6));
25	  std::complex<double> I3m563412 = I3m123456;
26	
27	  std::complex<double> result = 0.0;
28	
29	  if (st == hqpqbmgpgm) {
30	    result =
31	      - std::pow(zab2(j5,j2,j4,j1), 2) / (za(j5,j6)*zb(j1,j2)*std::pow(zab2(j3,j1,j2,j4), 2))
32	      * Lsm1_2mh(s(j3,j4), t(j1,j2,j4), s(j1,j2), s(j5,j6))
33	      - std::pow(zab2(j2,j1,j3,j6), 2) / (za(j1,j2)*zb(j5,j6)*std::pow(zab2(j3,j1,j2,j4), 2))
34	      * Lsm1_2mh(s(j3,j4), t(j1,j2,j3), s(j1,j2), s(j5,j6))
35	
36	      - I3m123456*za(j4,j5)*zb(j1,j3)
37	      * zab2(j2,j1,j3,j6) / (2.0*zab2(j3,j1,j2,j4)*t(j1,j2,j3))
38	
39	      - I3m123456*za(j2,j4)*zb(j3,j6)
40	      * zab2(j5,j2,j4,j1) / (2.0*zab2(j3,j1,j2,j4)*t(j1,j2,j4))
41	
42	      + I3m563412*za(j2,j4)*zb(j3,j6)
43	      * zab2(j5,j3,j6,j1) / (2.0*zab2(j3,j1,j2,j4)*t(j3,j5,j6))
44	
45	      + I3m563412*za(j4,j5)*zb(j1,j3)
46	      * zab2(j2,j4,j5,j6) / (2.0*zab2(j3,j1,j2,j4)*t(j4,j5,j6));
47	  } else if (st == hqpqbmgpgp) {
48	    result =
49	      - std::pow(za(j2,j5), 2) / (za(j1,j2)*za(j5,j6)*std::pow(za(j3,j4), 2))
50	      * Lsm1_2me(t(j1,j2,j3), t(j1,j2,j4), s(j1,j2), s(j5,j6));
51	  }
52	
53	  result = result; // @coverage-probe
54	  return result;
55	}
