6	//  Box coefficient for LL coupling.
7	//  Box D0(p1,p34,p2,mt,mt,mt,mt)
8	//  Opposite off-shellnesses: so called easy box.
9	//  Xpp and Xmp refer to the initial state gluon polarizations.
10	
11	#include "ZZbox1LL.hpp"
12	#include <cmath>
13	#include <complex>
14	#include <constants_mod.hpp>
15	#include <mxpart_mod.hpp>
16	#include <sprods_com_mod.hpp>
17	
18	// Internal helper: core box-coefficient computation for one pair of helicity
19	// conventions.  Called twice from ZZbox1LL with za/zb swapped to fill the
20	// full set of helicity coefficients.
21	static void ZZbox1LLcore(int j1, int j2, int j3, int j4, int j5, int j6,
22	                          FArray2D<std::complex<double>>& za,
23	                          FArray2D<std::complex<double>>& zb,
24	                          double mt,
25	                          FArray2D<std::complex<double>>& Xpp,
26	                          FArray2D<std::complex<double>>& Xmp,
27	                          FArray4D<std::complex<double>>& Xrat) {
28	  using namespace constants_mod;
29	  using namespace sprods_com_mod;
30	
31	  // Statement functions translated as lambdas
32	  auto zab2 = [&](int k1, int k2, int k3, int k4) -> std::complex<double> {
33	    return za(k1,k2)*zb(k2,k4) + za(k1,k3)*zb(k3,k4);
34	  };
35	
36	  auto funcpp2 = [&](int k1, int k2, int k3, int k4, int k5, int k6) -> std::complex<double> {
37	    return -half*(
38	        + za(k1,k3)*za(k2,k5)*za(k3,k4)*zb(k4,k2)*zb(k4,k3)*zb(k6,k1)
39	        + za(k1,k3)*za(k1,k5)*za(k2,k3)*zb(k2,k1)*zb(k4,k3)*zb(k6,k1)
40	        - za(k1,k2)*za(k3,k4)*za(k3,k5)*zb(k4,k2)*zb(k4,k3)*zb(k6,k1)
41	        - za(k1,k5)*za(k2,k3)*zab2(k5,k3,k4,k2)*zb(k4,k1)*zb(k6,k5)
42	        - 4.0*std::pow(za(k1,k5)*za(k2,k3),2)*zb(k2,k1)*zb(k4,k3)*zb(k6,k5)
43	          /za(k1,k2)
44	        - za(k1,k3)*za(k2,k5)*za(k3,k5)*zb(k2,k1)*zb(k4,k3)*zb(k6,k5)
45	        + za(k1,k2)*std::pow(za(k3,k5),2)*zb(k2,k1)*zb(k4,k3)*zb(k6,k5)
46	    ) / (std::pow(za(k1,k2),2)*s(k3,k4)*s(k5,k6));
47	  };
48	
49	  auto funcmp2 = [&](int k1, int k2, int k3, int k4, int k5, int k6) -> std::complex<double> {
50	    return half*(
51	        - za(k5,k6)*zab2(k1,k3,k4,k2)*zab2(k3,k2,k4,k1)
52	          *zb(k4,k1)*std::pow(zb(k6,k2),2)
53	          / (zab2(k2,k3,k4,k1)*std::pow(zb(k2,k1),2))
54	        + std::pow(za(k1,k5),2)*za(k2,k3)
55	          *zab2(k1,k3,k4,k2)*zab2(k2,k1,k3,k4)*zb(k6,k5)
56	          / (std::pow(za(k1,k2),2)*zab2(k2,k3,k4,k1))
57	    ) / (s(k3,k4)*s(k5,k6));
58	  };
59	
60	  double mtsq = mt*mt;
61	
62	  int k1 = j1;
63	  int k2 = j2;
64	  int k3, k4, k5, k6;
65	
66	  for (int h3 = 1; h3 <= 2; h3++) {
67	    if (h3 == 1) { k3 = j3; k4 = j4; }
68	    else          { k3 = j4; k4 = j3; }
69	
70	    for (int h5 = 1; h5 <= 2; h5++) {
71	      if (h5 == 1) { k5 = j5; k6 = j6; }
72	      else          { k5 = j6; k6 = j5; }
73	
74	      double s134 = s(k1,k3) + s(k1,k4) + s(k3,k4);
75	      double s234 = s(k2,k3) + s(k2,k4) + s(k3,k4);
76	
77	      // Helicity 1^+ 2^+
78	      auto app0 = half*(two*za(k3,k2)*za(k3,k1)*za(k2,k5)*za(k1,k5)
79	                        + std::pow(za(k3,k5)*za(k1,k2),2))
80	                  * (s134*s234 - s(k3,k4)*s(k5,k6))
81	                  / (std::pow(za(k1,k2),4)*za(k3,k4)*za(k5,k6));
82	
83	      auto app2 = funcpp2(k1,k2,k3,k4,k5,k6) + funcpp2(k2,k1,k3,k4,k5,k6);
84	
85	      auto app4 = two/(s(k3,k4)*s(k5,k6)*std::pow(za(k1,k2),2))
86	                  * (zb(k4,k1)*zab2(k1,k3,k4,k2)*za(k2,k5)
87	                     - zb(k4,k2)*zab2(k2,k3,k4,k1)*za(k1,k5))
88	                  * (za(k1,k3)*zb(k6,k2)/zab2(k1,k3,k4,k2)
89	                     - za(k2,k3)*zb(k6,k1)/zab2(k2,k3,k4,k1));
90	
91	      Xpp(h3,h5) = app0 + mtsq*app2 + mtsq*mtsq*app4; // @coverage-probe
92	      // contribution to rational part (coefficient of mt^4)
93	      Xrat(2,2,h3,h5) = app4;
94	
95	      // Helicity 1^- 2^+
96	      auto amp2 = funcmp2(k1,k2,k3,k4,k5,k6) + funcmp2(k1,k2,k5,k6,k3,k4);
97	
98	      auto amp4 = two/(s(j1,j2)*s(k3,k4)*s(k5,k6)*std::pow(zab2(k2,k3,k4,k1),2))
99	                  * (za(k2,k5)*zb(k1,k4)*zab2(k1,k3,k4,k2)
100	                     - za(k1,k5)*zb(k2,k4)*zab2(k2,k3,k4,k1))
101	                  * (za(k2,k3)*zb(k1,k6)*zab2(k1,k3,k4,k2)
102	                     - za(k1,k3)*zb(k2,k6)*zab2(k2,k3,k4,k1));
103	
104	      Xmp(h3,h5) = mtsq*amp2 + mtsq*mtsq*amp4;
105	      // contribution to rational part (coefficient of mt^4)
106	      Xrat(1,2,h3,h5) = amp4;
107	    }
108	  }
109	}
