111	void ZZbox1LL(int j1, int j2, int j3, int j4, int j5, int j6,
112	              FArray2D<std::complex<double>>& za,
113	              FArray2D<std::complex<double>>& zb,
114	              double mt,
115	              FArray2D<std::complex<double>>& Xpp,
116	              FArray2D<std::complex<double>>& Xmp,
117	              FArray2D<std::complex<double>>& Xpm,
118	              FArray2D<std::complex<double>>& Xmm,
119	              FArray4D<std::complex<double>>& Xrat) {
120	
121	  // First call with za and zb swapped; fills Xpp, Xmp, Xrat(2,2), Xrat(1,2)
122	  // from the conjugate helicity convention.
123	  ZZbox1LLcore(j1, j2, j3, j4, j5, j6, zb, za, mt, Xpp, Xmp, Xrat);
124	
125	  // Use results of first call to fill Xpm, Xmm, and the remaining Xrat entries.
126	  for (int h3 = 1; h3 <= 2; h3++) {
127	    for (int h5 = 1; h5 <= 2; h5++) {
128	      Xpm(h3,h5)          = Xmp(3-h3, 3-h5);
129	      Xmm(h3,h5)          = Xpp(3-h3, 3-h5);
130	      Xrat(2,1,h3,h5)     = Xrat(1,2, 3-h3, 3-h5);
131	      Xrat(1,1,h3,h5)     = Xrat(2,2, 3-h3, 3-h5);
132	    }
133	  }
134	
135	  // Second call with normal za, zb order; overwrites Xpp, Xmp, Xrat(2,2), Xrat(1,2).
136	  ZZbox1LLcore(j1, j2, j3, j4, j5, j6, za, zb, mt, Xpp, Xmp, Xrat);
137	}
